let queue = [];
let nextId = 1;
const list = document.getElementById("queue");

function addPatient(name) {
  if (name.trim() === "") return;
  queue.push({ id: nextId++, name: name.trim(), seen: false });   // 1. change state
  render();                                                        // 2. redraw
}

function toggleSeen(id) {
  const p = queue.find((x) => x.id === id);   // by id, never by position
  if (p) p.seen = !p.seen;
  render();
}

function render() {
  list.innerHTML = "";                         // empty first, or items double up
  for (const p of queue) {
    const li = document.createElement("li");
    li.textContent = p.name;
    li.classList.toggle("seen", p.seen);
    li.addEventListener("click", () => toggleSeen(p.id));   // remembers this p
    list.appendChild(li);
  }
}

