function addPatient(queue, name) {
  const clean = String(name).trim();
  if (clean === "") return [...queue];
  const id = queue.reduce((max, p) => Math.max(max, p.id), 0) + 1;
  return [...queue, { id, name: clean, seen: false }];
}

function toggleSeen(queue, id) {
  // a copy of the one that changes; the others are kept as they are
  return queue.map((p) => (p.id === id ? { ...p, seen: !p.seen } : p));
}

function removePatient(queue, id) {
  return queue.filter((p) => p.id !== id);
}

